"use strict";(globalThis.webpackChunkscraut_docs=globalThis.webpackChunkscraut_docs||[]).push([[5064],{4723(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"docsSidebar":[{"type":"link","href":"/scraut/","label":"What is Scraut?","docId":"intro","unlisted":false},{"type":"link","href":"/scraut/scrum-primer","label":"Scrum Primer","docId":"scrum-primer","unlisted":false},{"type":"category","label":"Getting Started","collapsed":false,"items":[{"type":"link","href":"/scraut/getting-started/prerequisites","label":"Prerequisites","docId":"getting-started/prerequisites","unlisted":false},{"type":"link","href":"/scraut/getting-started/installation","label":"Installation","docId":"getting-started/installation","unlisted":false},{"type":"link","href":"/scraut/getting-started/configuration","label":"Configuration","docId":"getting-started/configuration","unlisted":false},{"type":"link","href":"/scraut/getting-started/github-setup","label":"GitHub Setup","docId":"getting-started/github-setup","unlisted":false},{"type":"link","href":"/scraut/getting-started/first-sprint","label":"Your First Sprint","docId":"getting-started/first-sprint","unlisted":false}],"collapsible":true},{"type":"category","label":"Daily Workflows","items":[{"type":"link","href":"/scraut/daily-workflows/morning-routine","label":"Morning Routine","docId":"daily-workflows/morning-routine","unlisted":false},{"type":"link","href":"/scraut/daily-workflows/standup","label":"Daily Standup","docId":"daily-workflows/standup","unlisted":false},{"type":"link","href":"/scraut/daily-workflows/status","label":"Checking Sprint Status","docId":"daily-workflows/status","unlisted":false},{"type":"link","href":"/scraut/daily-workflows/blockers","label":"Adding Blockers","docId":"daily-workflows/blockers","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Scrum Ceremonies","items":[{"type":"link","href":"/scraut/ceremonies/sprint-planning","label":"Sprint Planning","docId":"ceremonies/sprint-planning","unlisted":false},{"type":"link","href":"/scraut/ceremonies/sprint-review","label":"Sprint Review","docId":"ceremonies/sprint-review","unlisted":false},{"type":"link","href":"/scraut/ceremonies/retrospective","label":"Sprint Retrospective","docId":"ceremonies/retrospective","unlisted":false},{"type":"link","href":"/scraut/ceremonies/backlog-grooming","label":"Backlog Grooming","docId":"ceremonies/backlog-grooming","unlisted":false},{"type":"link","href":"/scraut/ceremonies/estimation","label":"Estimation","docId":"ceremonies/estimation","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Features","items":[{"type":"link","href":"/scraut/features/velocity","label":"Velocity Tracking","docId":"features/velocity","unlisted":false},{"type":"link","href":"/scraut/features/milestones","label":"Milestone Planning","docId":"features/milestones","unlisted":false},{"type":"link","href":"/scraut/features/definition-of-done","label":"Definition of Done","docId":"features/definition-of-done","unlisted":false},{"type":"link","href":"/scraut/features/issue-triage","label":"Issue Triage & PR Linking","docId":"features/issue-triage","unlisted":false},{"type":"link","href":"/scraut/features/visibility-portal","label":"Visibility Portal","docId":"features/visibility-portal","unlisted":false},{"type":"link","href":"/scraut/features/suggestions","label":"Suggestions System","docId":"features/suggestions","unlisted":false},{"type":"link","href":"/scraut/features/standup-coach","label":"Standup Coach","docId":"features/standup-coach","unlisted":false},{"type":"link","href":"/scraut/features/notifications","label":"Notifications","docId":"features/notifications","unlisted":false},{"type":"link","href":"/scraut/features/repo-sync","label":"Repo Sync","docId":"features/repo-sync","unlisted":false},{"type":"link","href":"/scraut/features/incidents","label":"Incident Management","docId":"features/incidents","unlisted":false},{"type":"link","href":"/scraut/features/weekly-digest","label":"Weekly Digest","docId":"features/weekly-digest","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Agent Mode","items":[{"type":"link","href":"/scraut/agent-mode/overview","label":"Agent Mode Overview","docId":"agent-mode/overview","unlisted":false},{"type":"link","href":"/scraut/agent-mode/roles","label":"Agent Roles","docId":"agent-mode/roles","unlisted":false},{"type":"link","href":"/scraut/agent-mode/autonomy-levels","label":"Autonomy Levels","docId":"agent-mode/autonomy-levels","unlisted":false},{"type":"link","href":"/scraut/agent-mode/human-checkpoints","label":"Human Checkpoints","docId":"agent-mode/human-checkpoints","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Reference","items":[{"type":"link","href":"/scraut/reference/cli","label":"CLI Reference","docId":"reference/cli","unlisted":false},{"type":"link","href":"/scraut/reference/configuration","label":"Configuration Reference","docId":"reference/configuration","unlisted":false},{"type":"link","href":"/scraut/reference/team-roles","label":"Team Roles","docId":"reference/team-roles","unlisted":false},{"type":"link","href":"/scraut/reference/workflows","label":"GitHub Actions Workflows","docId":"reference/workflows","unlisted":false},{"type":"link","href":"/scraut/reference/file-structure","label":"File Structure","docId":"reference/file-structure","unlisted":false},{"type":"link","href":"/scraut/reference/workspace-formats","label":"Workspace File Formats","docId":"reference/workspace-formats","unlisted":false},{"type":"link","href":"/scraut/reference/llm-providers","label":"LLM Providers","docId":"reference/llm-providers","unlisted":false},{"type":"link","href":"/scraut/reference/labels","label":"GitHub Labels Reference","docId":"reference/labels","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"link","href":"/scraut/faq","label":"FAQ","docId":"faq","unlisted":false}]},"docs":{"agent-mode/autonomy-levels":{"id":"agent-mode/autonomy-levels","title":"Autonomy Levels","description":"Scraut offers three levels of agent autonomy. Choose based on your team\'s comfort with AI-driven automation.","sidebar":"docsSidebar"},"agent-mode/human-checkpoints":{"id":"agent-mode/human-checkpoints","title":"Human Checkpoints","description":"Human checkpoints are automatic pause points built into agent mode. When a checkpoint triggers, agents stop working and wait for a human to review and resume. They are the safety net that keeps humans in control even in semi-auto and full-auto modes.","sidebar":"docsSidebar"},"agent-mode/overview":{"id":"agent-mode/overview","title":"Agent Mode Overview","description":"Agent Mode is Scraut\'s fully autonomous AI development capability. When enabled, AI agents participate as team members \u2014 claiming issues, writing code, opening PRs, and submitting daily standups \u2014 alongside your human developers.","sidebar":"docsSidebar"},"agent-mode/roles":{"id":"agent-mode/roles","title":"Agent Roles","description":"Scraut has five built-in agent roles. Each is a separate GitHub Actions workflow with a distinct specialty. You enable only the agents your team needs.","sidebar":"docsSidebar"},"ceremonies/backlog-grooming":{"id":"ceremonies/backlog-grooming","title":"Backlog Grooming","description":"Backlog grooming happens automatically every Wednesday mid-sprint. Scraut reviews the current backlog, prioritises unlabelled issues, checks for scope creep, and posts recommendations to Slack \u2014 all without a meeting.","sidebar":"docsSidebar"},"ceremonies/estimation":{"id":"ceremonies/estimation","title":"Estimation","description":"Scraut supports async story point estimation using GitHub emoji reactions \u2014 no planning poker tool required.","sidebar":"docsSidebar"},"ceremonies/retrospective":{"id":"ceremonies/retrospective","title":"Sprint Retrospective","description":"The retrospective is the team\'s reflective ceremony. Each member writes their personal retro file, then the Scrum Master triggers a synthesis that produces a unified retrospective document with themes, patterns, and action items.","sidebar":"docsSidebar"},"ceremonies/sprint-planning":{"id":"ceremonies/sprint-planning","title":"Sprint Planning","description":"Sprint planning is a manual trigger ceremony where the Scrum Master initiates the sprint by clicking one button in GitHub Actions. Scraut then reads your backlog, team capacity, and OKRs to generate a proposed sprint plan as a pull request.","sidebar":"docsSidebar"},"ceremonies/sprint-review":{"id":"ceremonies/sprint-review","title":"Sprint Review","description":"The sprint review happens at the end of each sprint. The Scrum Master triggers it from GitHub Actions, and Scraut generates a comprehensive review document from the sprint\'s closed issues, velocity data, and standup summaries.","sidebar":"docsSidebar"},"daily-workflows/blockers":{"id":"daily-workflows/blockers","title":"Adding Blockers","description":"Blockers can be added to your standup file manually or via the scraut blocker command for a quick terminal shortcut.","sidebar":"docsSidebar"},"daily-workflows/morning-routine":{"id":"daily-workflows/morning-routine","title":"Morning Routine","description":"Every weekday morning, Scraut kicks off a routine that prepares each team member for the day.","sidebar":"docsSidebar"},"daily-workflows/standup":{"id":"daily-workflows/standup","title":"Daily Standup","description":"The standup is Scraut\'s core daily ceremony. Instead of a synchronous meeting, each team member writes a short Markdown file. The bot reads all files, generates a unified summary, and posts it to Slack \u2014 all automatically.","sidebar":"docsSidebar"},"daily-workflows/status":{"id":"daily-workflows/status","title":"Checking Sprint Status","description":"At any point during a sprint, you can see the current health of your sprint \u2014 story points completed, blockers, and milestone forecasts \u2014 directly from the terminal.","sidebar":"docsSidebar"},"faq":{"id":"faq","title":"FAQ","description":"Common questions about setting up and using Scraut.","sidebar":"docsSidebar"},"features/definition-of-done":{"id":"features/definition-of-done","title":"Definition of Done","description":"When a sprint issue is closed in GitHub, Scraut automatically checks whether it meets your team\'s Definition of Done (DoD). If the criteria aren\'t met, the issue is flagged.","sidebar":"docsSidebar"},"features/incidents":{"id":"features/incidents","title":"Incident Management","description":"When production incidents happen, Scraut helps capture action items and automatically converts them into tracked GitHub issues so nothing falls through the cracks.","sidebar":"docsSidebar"},"features/issue-triage":{"id":"features/issue-triage","title":"Issue Triage & PR Linking","description":"Two automatic workflows fire whenever issues and pull requests are created, keeping your backlog organised without manual labelling effort.","sidebar":"docsSidebar"},"features/milestones":{"id":"features/milestones","title":"Milestone Planning","description":"Milestones let you plan and track multi-sprint goals (releases, product versions, major features). Scraut automatically decomposes milestones into epics, tracks health, and generates forecasts.","sidebar":"docsSidebar"},"features/notifications":{"id":"features/notifications","title":"Notifications","description":"Scraut sends targeted Slack notifications at key moments \u2014 morning reminders, ceremony summaries, blocker alerts, and more. All notifications are opt-in and configurable.","sidebar":"docsSidebar"},"features/repo-sync":{"id":"features/repo-sync","title":"Repo Sync","description":"If your team works across multiple GitHub repositories (e.g., a separate backend API repo, a mobile repo, a shared library), Repo Sync pulls code activity from those connected repos and makes it available in each morning\'s standup context.","sidebar":"docsSidebar"},"features/standup-coach":{"id":"features/standup-coach","title":"Standup Coach","description":"The Standup Coach is an opt-in daily assistant that detects when a team member\'s standup Today section is light on specifics \u2014 no issue references, no concrete tasks \u2014 and sends them a private Slack DM with personalised task recommendations. Nothing is posted to the team channel.","sidebar":"docsSidebar"},"features/suggestions":{"id":"features/suggestions","title":"Suggestions System","description":"The Suggestions system is Scraut\'s continuous process improvement engine. After each sprint review, it analyses patterns across your sprint history and proposes targeted improvements to your team\'s workflow.","sidebar":"docsSidebar"},"features/velocity":{"id":"features/velocity","title":"Velocity Tracking","description":"Scraut automatically calculates sprint velocity and maintains a rolling average, which feeds into sprint planning capacity estimates.","sidebar":"docsSidebar"},"features/visibility-portal":{"id":"features/visibility-portal","title":"Visibility Portal","description":"The Visibility Portal is a GitHub Pages dashboard that gives stakeholders a real-time view of sprint progress, team velocity, and milestone health \u2014 without needing access to GitHub issues or source code.","sidebar":"docsSidebar"},"features/weekly-digest":{"id":"features/weekly-digest","title":"Weekly Digest","description":"Every Monday morning, Scraut sends a stakeholder digest that summarises the previous week\'s progress, velocity trends, and upcoming sprint goals. This keeps managers and stakeholders informed without requiring status calls.","sidebar":"docsSidebar"},"getting-started/configuration":{"id":"getting-started/configuration","title":"Configuration","description":"All configuration lives in workspace/scraut.yml. This file is the single source of truth for your team settings, sprint configuration, and feature toggles.","sidebar":"docsSidebar"},"getting-started/first-sprint":{"id":"getting-started/first-sprint","title":"Your First Sprint","description":"With Scraut installed and GitHub configured, this guide walks you through launching Sprint 1 end-to-end.","sidebar":"docsSidebar"},"getting-started/github-setup":{"id":"getting-started/github-setup","title":"GitHub Setup","description":"Scraut requires a few one-time setup steps in your GitHub repository settings before workflows can run.","sidebar":"docsSidebar"},"getting-started/installation":{"id":"getting-started/installation","title":"Installation","description":"There are two ways to set up Scraut. Both produce identical results \u2014 choose the one that fits your workflow.","sidebar":"docsSidebar"},"getting-started/prerequisites":{"id":"getting-started/prerequisites","title":"Prerequisites","description":"If your team is new to Scrum, read the Scrum Primer before continuing \u2014 it explains the ceremonies, roles, artifacts, and the hard rules Scraut is built around.","sidebar":"docsSidebar"},"intro":{"id":"intro","title":"What is Scraut?","description":"Scraut (Scrum Automation) is a fully automated Scrum system built on GitHub infrastructure. It replaces Scrum-management apps and reduces ceremony overhead by treating text files as the single source of truth and letting GitHub Actions + an LLM do the rest.","sidebar":"docsSidebar"},"reference/cli":{"id":"reference/cli","title":"CLI Reference","description":"The scraut CLI provides quick terminal shortcuts for common daily tasks. Install it once, use it every day.","sidebar":"docsSidebar"},"reference/configuration":{"id":"reference/configuration","title":"Configuration Reference","description":"Full reference for every field in workspace/scraut.yml.","sidebar":"docsSidebar"},"reference/file-structure":{"id":"reference/file-structure","title":"File Structure","description":"Complete reference of the Scraut repository layout and every significant file.","sidebar":"docsSidebar"},"reference/labels":{"id":"reference/labels","title":"GitHub Labels Reference","description":"Scraut uses a specific set of GitHub labels for story points, type, priority, status, ceremony, agent state, and Definition of Done. These are created automatically by scraut init or npx create-scraut when GITHUB_TOKEN is set.","sidebar":"docsSidebar"},"reference/llm-providers":{"id":"reference/llm-providers","title":"LLM Providers","description":"Scraut supports four LLM providers and custom endpoints. Configure your choice in workspace/scraut.yml.","sidebar":"docsSidebar"},"reference/team-roles":{"id":"reference/team-roles","title":"Team Roles","description":"Scraut has three places where you assign roles to people. This page explains what each does \u2014 and, importantly, what each does not do.","sidebar":"docsSidebar"},"reference/workflows":{"id":"reference/workflows","title":"GitHub Actions Workflows","description":"All Scraut automation runs as GitHub Actions workflows. This page covers every workflow, its trigger type, and what it does.","sidebar":"docsSidebar"},"reference/workspace-formats":{"id":"reference/workspace-formats","title":"Workspace File Formats","description":"Complete format reference for every file a team member writes under workspace/.","sidebar":"docsSidebar"},"scrum-primer":{"id":"scrum-primer","title":"Scrum Primer","description":"A complete overview of Scrum for teams that are new to the framework \u2014 covering concepts, ceremonies, artifacts, visual tools, and the hard rules that make it work. Each section notes how Scraut automates the corresponding piece.","sidebar":"docsSidebar"}}}}')}}]);